import React from 'react';
import { render, screen, act } from '@testing-library/react';
import App from './App';

// Mock Apollo client to avoid network calls during App render
jest.mock('@apollo/client', () => {
  const actual = jest.requireActual('@apollo/client');
  return {
    ...actual,
    HttpLink: jest.fn().mockImplementation(() => ({})),
  };
});

describe('App Component', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test('renders splash screen initially', () => {
    render(<App />);
    const splash = screen.getByRole('status', { name: /loading hegmakart/i });
    expect(splash).toBeInTheDocument();
  });

  test('transitions after splash screen timeout', () => {
    render(<App />);
    expect(screen.getByRole('status', { name: /loading hegmakart/i })).toBeInTheDocument();

    act(() => {
      jest.advanceTimersByTime(2100);
    });

    // Splashscreen is removed
    expect(screen.queryByRole('status', { name: /loading hegmakart/i })).not.toBeInTheDocument();
  });
});
